```scala
object Main {
  /**
   * Checks if all elements in a list are identical.
   * @param list The input list.
   * @tparam T The type of the list elements.
   * @return True if all elements are identical, false otherwise.
   */
  def allIdentical[T](list: List[T]): Boolean = {
    list match {
      case Nil => true // An empty list has all identical elements (vacuously true)
      case head :: Nil => true // A list with one element has all identical elements
      case head :: tail => tail.forall(_ == head)
    }
  }

